import json
import sys

def load_data(file_path):
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {"rallies": []}

def save_data(data, file_path):
    with open(file_path, 'w') as f:
        json.dump(data, f, indent=2)

def add_rally(data, serve_time_sec, ending_time_sec, ending, strokes):
    rally = {
        "serve_time_sec": serve_time_sec,
        "strokes": strokes,
        "ending_time_sec": ending_time_sec,
        "ending": ending
    }
    data["rallies"].append(rally)
    return data
